"""EW rectifier bus sizing from a heat balance (AQS-BUS-001 rev C, A-M-173). Each cell bar is a pack of n flat copper bars of thickness t
and width w, spaced one thickness apart [CDA_PUB22]. Heat generated per metre I^2 rho(T)/A must not exceed what the pack sheds by free
convection (vertical-plate laminar correlation Nu = 0.59 Ra^0.25 on the bar width [INCROPERA7]) plus radiation eps sigma (T^4 - Ta^4)
on the outer surface only [CDA_PUB22] at the allowed rise. The section also keeps the UL891 default density of 1000 A/in2 (155 A/cm2), the same rule the switchboard bus uses in AQS-ELEC-010. Width steps 10 mm up to 160 mm, then another bar is added.
Drop over the 2 m run plus the bolted joints is checked against the 0.3 V bus-drop budget the rectifier and graph use (ew_bus_drop_V).
Run: python3 docs-authority/_ew_busbar.py"""
import os, re, sys
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); sys.path.insert(0, R)
from flow_graph.param import drivers as DR
d = DR.load(); v = lambda k: DR.val(d, k)
SIG = 5.670e-8; Ta = 313.15
def shed(w, t, n, dT):
    T = Ta + dT; Tf = (T + Ta)/2; nu = 1.6e-5*(Tf/300)**1.75; k = 0.0263*(Tf/300)**0.8; Pr = 0.71   # air, INCROPERA7 table A.4 fit
    Ra = 9.81/Tf*dT*w**3/nu**2*Pr; h = 0.59*Ra**0.25*k/w
    P_out = 2*(w + n*t + (n - 1)*t); P_conv = 2*n*w + 2*n*t                    # outer surface radiates; every face convects
    return h*P_conv*dT + v('ew_bar_emissivity')*SIG*(T**4 - Ta**4)*P_out
def size(I):
    t = v('ew_bar_t_mm')/1000; dT = v('ew_bar_rise_K'); rho = 1.724e-8*(1 + 0.00393*(Ta + dT - 293.15))
    for n in range(1, 9):
        for wmm in range(20, 170, 10):
            w = wmm/1000; A = n*w*t
            if I**2*rho/A <= shed(w, t, n, dT) and I/(A*1e4) <= 1000/6.4516: return dict(n=n, w_mm=wmm, A_cm2=A*1e4, J=I/(A*1e4), q_W_m=I**2*rho/A, drop_V=I*rho*v('ew_bar_L_m')/A*2)
def main():
    old = open(os.path.join(R, 'docs-authority/BUSBAR.md')).read()
    cells = [(c, int(a)) for c, a in re.findall(r'\| (EW-\d) \| (\d+) \|', old)]
    rows = [(c, I, size(I)) for c, I in cells]; bud = v('ew_bus_drop_V')
    md = ['# Rectifier bus', '', 'Document number: AQS-BUS-001', 'Revision: C', 'Date: 2026-10-16', 'Generated by `docs-authority/_ew_busbar.py`. Not a PE stamp. A-M-173.', '',
          f"1. Basis. Cell current from the duty pages. Each bar is a pack of {v('ew_bar_t_mm')} mm copper flats spaced one thickness apart (CDA_PUB22), sized so the I²R heat per metre is shed by free convection (INCROPERA7) and radiation (emissivity {v('ew_bar_emissivity')}, painted, CDA_PUB22) at a {v('ew_bar_rise_K'):.0f} K rise over 40 C, and held to the UL891 default 155 A/cm² (UL891). The heat balance alone allows about 220-250 A/cm² on these bars, so the density rule governs. Rev B used a flat 200 A/cm²; rev C replaces it.", '',
          f"2. Size. Resistivity 1.724e-8 ohm m at 20 C, 0.00393 /K (CDA_PUB22). Go and return run {v('ew_bar_L_m')} m each; joints {v('ew_contact_drop_V')*1000:.0f} mV. Budget {bud*1000:.0f} mV (ew_bus_drop_V, used by the rectifier and the graph).", '',
          '| Cell | A | cm² | Pack | A/cm² | Heat W/m | Drop mV | Within budget |', '|---|---:|---:|---|---:|---:|---:|---|']
    for c, I, s in rows:
        tot = s['drop_V'] + v('ew_contact_drop_V')
        md.append(f"| {c} | {I} | {s['A_cm2']:.1f} | {s['n']} x {s['w_mm']} x {v('ew_bar_t_mm')} mm | {s['J']:.0f} | {s['q_W_m']:.0f} | {tot*1000:.0f} | {'yes' if tot <= bud else 'NO'} |")
    md += ['', '3. Material. Copper C101 bar, painted. No aluminum on a wet aisle.', '', '4. Joints. Bolted at the rectifier and at the cell bus; joint overlap at least the bar width.', '',
           '5. Instruments. Cell voltage reads at the cell bus. A thermocouple on the largest bar verifies the rise at the RECT-EW first article (A-M-173).']
    open(os.path.join(R, 'docs-authority/BUSBAR.md'), 'w').write('\n'.join(md) + '\n'); print('\n'.join(md[-16:]))
if __name__ == '__main__': main()
